CREATE TABLE notificaciones (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id UUID NOT NULL REFERENCES empresas(id), usuario_id UUID NOT NULL REFERENCES usuarios(id), tipo VARCHAR(80) NOT NULL, categoria VARCHAR(30) NOT NULL, prioridad VARCHAR(20) NOT NULL DEFAULT 'NORMAL', titulo VARCHAR(200) NOT NULL, mensaje TEXT, entidad_tipo VARCHAR(50), entidad_id UUID, leida BOOLEAN NOT NULL DEFAULT FALSE, leida_en TIMESTAMP, creada_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_notificaciones_usuario_no_leidas ON notificaciones(empresa_id, usuario_id, leida, creada_en DESC);
